// Authored Yogabase Jobs facade test. This file is not generated by Microsoft Kiota.
//
// The shapes pinned here are the ones the product's gateway writes (DurableJobsGateway) and its developer
// documentation states. The product's client OpenAPI document does not describe the Jobs routes, which is
// why they are pinned by this test rather than by the mirrored contract.
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import test from "node:test";
import {
    YOGABASE_JOB_ERROR_CODES,
    YOGABASE_JOB_TERMINAL_STATUSES,
    YOGABASE_JOBS_LIMITS,
    YogabaseJobsClient,
    YogabaseJobsError,
} from "../dist/index.js";

const PROJECT = "11111111-1111-4111-8111-111111111111";
const JOB = "5d0a8f0e-3c63-4d5e-9a0b-7c1f3a9e2b41";
const JOBS = `https://apps.example.test/v1/projects/${PROJECT}/jobs`;

function fakeFetch(responses) {
    const calls = [];
    const fetcher = async (url, init) => {
        calls.push({ url: String(url), init });
        const next = responses.shift();
        if (typeof next === "function") return next(url, init);
        return next;
    };
    return { calls, fetcher };
}

function client(fake, options = {}) {
    return new YogabaseJobsClient({
        gatewayHost: "https://apps.example.test",
        projectId: PROJECT,
        accessToken: "user-token",
        fetch: fake.fetcher,
        ...options,
    });
}

function jobDocument(overrides = {}) {
    return {
        jobId: JOB,
        jobType: "orders-create",
        status: "Queued",
        attempt: 0,
        maxAttempts: 5,
        progressPercent: 0,
        cancellationRequested: false,
        resultReference: null,
        failureCode: null,
        createdAt: "2026-10-03T05:00:00+00:00",
        updatedAt: "2026-10-03T05:00:01+00:00",
        completedAt: null,
        ...overrides,
    };
}

function json(body, status = 200, headers = {}) {
    return new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json", ...headers } });
}

// What ASP.NET Core writes for Results.Problem(statusCode, title, detail, extensions): the code and the limits
// are top-level members beside type, title, status and traceId.
function problem(status, title, code, extras = {}) {
    return new Response(
        JSON.stringify({ type: "https://tools.ietf.org/html/rfc9110", title, status, traceId: "00-trace", code, ...extras }),
        { status, headers: { "Content-Type": "application/problem+json" } },
    );
}

function sha256(bytes) {
    return `sha256:${createHash("sha256").update(bytes).digest("hex")}`;
}

function resultResponse(bytes, digest, status = 200) {
    const headers = { "Content-Type": "application/octet-stream", "Cache-Control": "private, no-store" };
    if (digest !== undefined) headers["X-Yogabase-Content-Sha256"] = digest;
    return new Response(bytes, { status, headers });
}

