// Submit
// ------------------------------------------------------------------------------------------------

test("submit sends the exact route, body and user token and reads the accepted job", async () => {
    const fake = fakeFetch([json(jobDocument(), 202, { Location: `/v1/projects/${PROJECT}/jobs/${JOB}` })]);
    const job = await client(fake).submit({
        jobType: "orders-create",
        idempotencyKey: "order-42",
        payload: new TextEncoder().encode("hello"),
        maxAttempts: 3,
    });

    assert.equal(fake.calls[0].url, JOBS);
    assert.equal(fake.calls[0].init.method, "POST");
    assert.equal(fake.calls[0].init.headers.get("Authorization"), "Bearer user-token");
    assert.equal(fake.calls[0].init.headers.get("Content-Type"), "application/json");
    assert.equal(fake.calls[0].init.redirect, "error");
    // The member order and the names are the gateway's submission, which refuses any other member.
    assert.equal(fake.calls[0].init.body, '{"jobType":"orders-create","idempotencyKey":"order-42","payloadBase64":"aGVsbG8=","maxAttempts":3}');
    // The key rides in the body: the gateway reads no Idempotency-Key header on this route.
    assert.equal(fake.calls[0].init.headers.has("Idempotency-Key"), false);
    assert.deepEqual(job, jobDocument());
});

test("submit omits an absent or empty payload and an unset attempt budget", async () => {
    const fake = fakeFetch([json(jobDocument({ jobType: "emails-send" }), 202), json(jobDocument({ jobType: "emails-send" }), 202)]);
    const jobs = client(fake);
    await jobs.submit({ jobType: "emails-send", idempotencyKey: "k" });
    await jobs.submit({ jobType: "emails-send", idempotencyKey: "k", payload: new Uint8Array(0) });
    // A job with no payload and one with an empty payload are the same job to the gateway.
    assert.deepEqual(fake.calls.map(call => call.init.body), ['{"jobType":"emails-send","idempotencyKey":"k"}', '{"jobType":"emails-send","idempotencyKey":"k"}']);
});

test("a retried submit is the same request on the wire, so the gateway can replay it", async () => {
    const fake = fakeFetch([json(jobDocument(), 202), json(jobDocument({ status: "Running" }), 202)]);
    const jobs = client(fake);
    const request = { jobType: "orders-create", idempotencyKey: "order-42", payload: Uint8Array.of(1, 2, 3) };
    const first = await jobs.submit(request);
    const replay = await jobs.submit(request);
    assert.equal(fake.calls[0].init.body, fake.calls[1].init.body);
    assert.equal(first.jobId, replay.jobId);
    // 202 again, whatever the job has become.
    assert.equal(replay.status, "Running");
});

test("a submit at exactly the inline limit is sent and one byte more is refused before the network", async () => {
    const fake = fakeFetch([json(jobDocument(), 202)]);
    const jobs = client(fake);
    await jobs.submit({ jobType: "orders-create", idempotencyKey: "k-max", payload: new Uint8Array(YOGABASE_JOBS_LIMITS.maximumPayloadBytes) });
    assert.equal(JSON.parse(fake.calls[0].init.body).payloadBase64.length, 1_398_104);
    await assert.rejects(
        jobs.submit({ jobType: "orders-create", idempotencyKey: "k-over", payload: new Uint8Array(YOGABASE_JOBS_LIMITS.maximumPayloadBytes + 1) }),
        RangeError,
    );
    assert.equal(fake.calls.length, 1);
});

test("a malformed submit is refused before the network", async () => {
    const fake = fakeFetch([]);
    const jobs = client(fake);
    const base = { jobType: "orders-create", idempotencyKey: "k" };
    const cases = [
        { ...base, jobType: "" },
        { ...base, jobType: "   " },
        { ...base, jobType: " orders-create" },
        { ...base, jobType: "orders-create " },
        { ...base, jobType: "orders create" },
        { ...base, jobType: "orders/create" },
        { ...base, jobType: "orders\ncreate" },
        { ...base, jobType: "ordérs" },
        { ...base, jobType: "a".repeat(129) },
        { ...base, idempotencyKey: "" },
        { ...base, idempotencyKey: "   " },
        { ...base, idempotencyKey: " padded" },
        { ...base, idempotencyKey: "padded " },
        { ...base, idempotencyKey: "has\ncontrol" },
        { ...base, idempotencyKey: "k".repeat(257) },
        { ...base, maxAttempts: 0 },
        { ...base, maxAttempts: 11 },
        { ...base, maxAttempts: 2.5 },
        { ...base, payload: "not bytes" },
    ];
    for (const request of cases) {
        await assert.rejects(jobs.submit(request), error => error instanceof RangeError || error instanceof TypeError, JSON.stringify(request));
    }
    assert.equal(fake.calls.length, 0);
});

test("the longest job type and idempotency key are sent", async () => {
    const fake = fakeFetch([json(jobDocument({ jobType: "a".repeat(128) }), 202)]);
    await client(fake).submit({ jobType: "a".repeat(128), idempotencyKey: "k".repeat(256) });
    assert.equal(fake.calls.length, 1);
});

