test("a submit the gateway refuses surfaces its status and code", async () => {
    for (const [status, code, title] of [
        [409, YOGABASE_JOB_ERROR_CODES.idempotencyConflict, "The idempotency key belongs to a different job request."],
        [422, YOGABASE_JOB_ERROR_CODES.typeNotRegistered, "The job type is not registered."],
        [400, YOGABASE_JOB_ERROR_CODES.requestInvalid, "Invalid job request."],
        [403, YOGABASE_JOB_ERROR_CODES.accessDenied, "Job access denied."],
        [503, YOGABASE_JOB_ERROR_CODES.unavailable, "Job persistence unavailable."],
    ]) {
        const fake = fakeFetch([problem(status, title, code)]);
        await assert.rejects(
            client(fake).submit({ jobType: "orders-create", idempotencyKey: "k" }),
            error => error instanceof YogabaseJobsError
                && error.status === status && error.code === code && error.message === title
                && error.limitBytes === undefined && error.maxBodyBytes === undefined,
            `${status} ${code}`,
        );
    }
});

test("a payload-too-large refusal names the limits it carries", async () => {
    const fake = fakeFetch([problem(413, "The job payload is too large.", "job_payload_too_large", {
        detail: "A job payload may be at most 1048576 bytes before base64 encoding, and the whole request body at most 8391225 bytes.",
        limitBytes: 1_048_576,
        maxBodyBytes: 8_391_225,
    })]);
    await assert.rejects(
        client(fake).submit({ jobType: "orders-create", idempotencyKey: "k", payload: Uint8Array.of(1) }),
        error => error instanceof YogabaseJobsError
            && error.status === 413 && error.code === "job_payload_too_large"
            && error.limitBytes === 1_048_576 && error.maxBodyBytes === 8_391_225
            && error.message.includes("8391225"),
    );
});

test("a bare 413 from a gateway that predates the named refusal reads as payload_too_large", async () => {
    const fake = fakeFetch([new Response(null, { status: 413 })]);
    await assert.rejects(
        client(fake).submit({ jobType: "orders-create", idempotencyKey: "k" }),
        error => error instanceof YogabaseJobsError && error.status === 413 && error.code === "payload_too_large" && error.limitBytes === undefined,
    );
});

test("an installation without Jobs answers a plain not_found that is not job_not_found", async () => {
    const fake = fakeFetch([new Response(null, { status: 404 })]);
    await assert.rejects(
        client(fake).get(JOB),
        error => error instanceof YogabaseJobsError && error.status === 404 && error.code === "not_found" && error.code !== YOGABASE_JOB_ERROR_CODES.notFound,
    );
});

test("limits that are not positive whole numbers are not reported", async () => {
    const fake = fakeFetch([problem(413, "x", "job_payload_too_large", { limitBytes: -1, maxBodyBytes: "8391225" })]);
    await assert.rejects(
        client(fake).submit({ jobType: "orders-create", idempotencyKey: "k" }),
        error => error.limitBytes === undefined && error.maxBodyBytes === undefined,
    );
});

