test("get reads one job by its route and maps every field", async () => {
    const document = jobDocument({
        status: "Succeeded", attempt: 2, maxAttempts: 3, progressPercent: 100,
        resultReference: "object://invocation-payload/abc/def", failureCode: "handler_retry", completedAt: "2026-10-03T05:00:09+00:00",
    });
    const fake = fakeFetch([json(document)]);
    const job = await client(fake).get(JOB);
    assert.equal(fake.calls[0].url, `${JOBS}/${JOB}`);
    assert.equal(fake.calls[0].init.method, "GET");
    assert.equal(fake.calls[0].init.body, undefined);
    assert.equal(fake.calls[0].init.headers.get("Authorization"), "Bearer user-token");
    assert.deepEqual(job, document);
});

test("every status is read and only the settled ones are terminal", async () => {
    for (const status of ["Queued", "Running", "Succeeded", "Failed", "Cancelled", "DeadLettered"]) {
        const fake = fakeFetch([json(jobDocument({ status }))]);
        const job = await client(fake).get(JOB);
        assert.equal(job.status, status);
        assert.equal(YOGABASE_JOB_TERMINAL_STATUSES.includes(job.status), ["Succeeded", "Cancelled", "DeadLettered"].includes(status), status);
    }
});

test("another user's job and an unknown job are the same not found, to a read and to a cancel", async () => {
    const fake = fakeFetch([
        problem(404, "Job not found.", "job_not_found"),
        problem(404, "Job not found.", "job_not_found"),
    ]);
    const jobs = client(fake);
    for (const call of [() => jobs.get(JOB), () => jobs.cancel(JOB)]) {
        await assert.rejects(call(), error => error instanceof YogabaseJobsError && error.status === 404 && error.code === "job_not_found");
    }
});

test("cancel posts to the cancel route with no body and reads the job", async () => {
    const fake = fakeFetch([json(jobDocument({ status: "Running", cancellationRequested: true }))]);
    const job = await client(fake).cancel(JOB);
    assert.equal(fake.calls[0].url, `${JOBS}/${JOB}/cancel`);
    assert.equal(fake.calls[0].init.method, "POST");
    assert.equal(fake.calls[0].init.body, undefined);
    assert.equal(fake.calls[0].init.headers.has("Content-Type"), false);
    // A running job is flagged and stopped by its worker, so the flag can be set while it still runs.
    assert.equal(job.cancellationRequested, true);
    assert.equal(job.status, "Running");
});

test("a job id that is not a non-empty canonical UUID is refused before the network on every route", async () => {
    const fake = fakeFetch([]);
    const jobs = client(fake);
    for (const id of ["", "not-a-guid", "00000000-0000-0000-0000-000000000000", JOB.replaceAll("-", ""), `${JOB}/../x`]) {
        for (const call of [() => jobs.get(id), () => jobs.cancel(id), () => jobs.result(id)]) {
            await assert.rejects(call(), TypeError, id);
        }
    }
    assert.equal(fake.calls.length, 0);
});

test("the access token provider is asked for each call, and an empty token is refused", async () => {
    let issued = 0;
    const fake = fakeFetch([json(jobDocument()), json(jobDocument())]);
    const jobs = client(fake, { accessToken: async () => `token-${++issued}` });
    await jobs.get(JOB);
    await jobs.get(JOB);
    assert.deepEqual(fake.calls.map(call => call.init.headers.get("Authorization")), ["Bearer token-1", "Bearer token-2"]);

    const empty = client(fakeFetch([]), { accessToken: () => "" });
    await assert.rejects(empty.get(JOB), TypeError);
});

test("an aborted signal stops a job call", async () => {
    const controller = new AbortController();
    controller.abort();
    const fake = fakeFetch([(_url, init) => {
        if (init.signal?.aborted) throw Object.assign(new Error("aborted"), { name: "AbortError" });
        return json(jobDocument());
    }]);
    await assert.rejects(client(fake).get(JOB, { signal: controller.signal }), error => error.name === "AbortError");
});

