test("a job the route does not declare is refused, not guessed at", async () => {
    const cases = [
        jobDocument({ status: "Paused" }),
        jobDocument({ status: 1 }),
        jobDocument({ status: "queued" }),
        jobDocument({ maxAttempts: 0 }),
        jobDocument({ maxAttempts: 11 }),
        jobDocument({ attempt: -1 }),
        jobDocument({ attempt: 1.5 }),
        jobDocument({ progressPercent: 101 }),
        jobDocument({ progressPercent: -1 }),
        jobDocument({ jobId: "not-a-guid" }),
        jobDocument({ jobId: "00000000-0000-0000-0000-000000000000" }),
        jobDocument({ jobType: "has space" }),
        jobDocument({ jobType: "" }),
        jobDocument({ failureCode: "Upper_Case" }),
        jobDocument({ resultReference: "https://elsewhere.example/result" }),
        jobDocument({ resultReference: "object://" }),
        jobDocument({ resultReference: "object://with space" }),
        jobDocument({ cancellationRequested: "false" }),
        jobDocument({ createdAt: "yesterday" }),
        jobDocument({ completedAt: "later" }),
        [],
        null,
        "a string",
    ];
    for (const document of cases) {
        const fake = fakeFetch([json(document)]);
        await assert.rejects(
            client(fake).get(JOB),
            error => error instanceof YogabaseJobsError && error.status === 502 && error.code === "job_response_invalid",
            JSON.stringify(document),
        );
    }
    const notJson = fakeFetch([new Response("not json", { status: 200 })]);
    await assert.rejects(client(notJson).get(JOB), error => error.code === "job_response_invalid");
});

test("a member this client does not know is kept out of the job and does not refuse it", async () => {
    const fake = fakeFetch([json({ ...jobDocument(), futureMember: { nested: true } })]);
    const job = await client(fake).get(JOB);
    assert.deepEqual(job, jobDocument());
});

