test("the result is read from its route and checked against the digest the gateway sent", async () => {
    for (const length of [1, 81_920, 300_001]) {
        const bytes = new Uint8Array(length).map((_, index) => (index * 31 + length) % 251);
        const digest = sha256(bytes);
        const fake = fakeFetch([resultResponse(bytes, digest)]);
        const result = await client(fake).result(JOB);
        assert.equal(fake.calls[0].url, `${JOBS}/${JOB}/result`);
        assert.equal(fake.calls[0].init.method, "GET");
        assert.equal(fake.calls[0].init.headers.get("Authorization"), "Bearer user-token");
        assert.equal(fake.calls[0].init.headers.get("Accept"), "application/octet-stream, application/problem+json");
        assert.deepEqual(Buffer.from(result.content), Buffer.from(bytes));
        assert.equal(result.digest, digest);
    }
});

test("a result that does not hash to its digest is not returned", async () => {
    const served = new TextEncoder().encode("what the store held");
    const claimed = sha256(new TextEncoder().encode("what the job recorded"));
    const fake = fakeFetch([resultResponse(served, claimed)]);
    await assert.rejects(
        client(fake).result(JOB),
        error => error instanceof YogabaseJobsError && error.status === 502 && error.code === "job_result_digest_mismatch"
            && !error.message.includes("what the store held"),
    );
});

test("a result without a well-formed digest is not trusted even if its bytes are right", async () => {
    const bytes = new TextEncoder().encode("hello");
    const right = sha256(bytes).slice("sha256:".length);
    const cases = [
        undefined,
        "",
        "sha256:",
        `SHA256:${right}`,
        `sha256:${right.toUpperCase()}`,
        `sha256:${right.slice(0, -1)}`,
        `sha256:${right}4`,
        `sha1:${right}`,
        right,
        `sha256:z${right.slice(1)}`,
    ];
    for (const digest of cases) {
        const fake = fakeFetch([resultResponse(bytes, digest)]);
        await assert.rejects(
            client(fake).result(JOB),
            error => error instanceof YogabaseJobsError && error.status === 502 && error.code === "job_response_invalid",
            String(digest),
        );
    }
});

test("a result with two digest headers is not trusted", async () => {
    const bytes = new TextEncoder().encode("hello");
    const digest = sha256(bytes);
    const response = new Response(bytes, { status: 200, headers: { "Content-Type": "application/octet-stream" } });
    response.headers.append("X-Yogabase-Content-Sha256", digest);
    response.headers.append("X-Yogabase-Content-Sha256", digest);
    await assert.rejects(client(fakeFetch([response])).result(JOB), error => error.code === "job_response_invalid");
});

test("a result larger than the bound is refused, declared or streamed", async () => {
    const declared = new Response(Uint8Array.of(1), {
        status: 200,
        headers: {
            "X-Yogabase-Content-Sha256": sha256(Uint8Array.of(1)),
            "Content-Length": String(YOGABASE_JOBS_LIMITS.maximumResultBytes + 1),
        },
    });
    await assert.rejects(client(fakeFetch([declared])).result(JOB), error => error.code === "job_response_invalid");

    const chunk = new Uint8Array(1_048_576);
    let sent = 0;
    const stream = new ReadableStream({
        pull(controller) {
            if (sent > 16) { controller.close(); return; }
            sent += 1;
            controller.enqueue(chunk);
        },
    });
    const streamed = new Response(stream, { status: 200, headers: { "X-Yogabase-Content-Sha256": sha256(chunk) } });
    await assert.rejects(client(fakeFetch([streamed])).result(JOB), error => error.code === "job_response_invalid");
});

test("a success that is not a 200 is not a result", async () => {
    const bytes = new TextEncoder().encode("hello");
    const fake = fakeFetch([resultResponse(bytes, sha256(bytes), 202)]);
    await assert.rejects(client(fake).result(JOB), error => error.code === "job_response_invalid");
});

test("a result the gateway refuses surfaces its status and code and no bytes", async () => {
    for (const [status, code, title] of [
        [409, YOGABASE_JOB_ERROR_CODES.resultNotReady, "The job has not settled, so it has no result yet."],
        [404, YOGABASE_JOB_ERROR_CODES.resultNotFound, "Job result not found."],
        [502, YOGABASE_JOB_ERROR_CODES.resultIntegrityFailed, "The stored result does not match what the job recorded."],
        [500, YOGABASE_JOB_ERROR_CODES.resultReferenceInvalid, "The job's stored result is not its own."],
        [503, YOGABASE_JOB_ERROR_CODES.unavailable, "Job persistence unavailable."],
    ]) {
        const fake = fakeFetch([problem(status, title, code)]);
        await assert.rejects(
            client(fake).result(JOB),
            error => error instanceof YogabaseJobsError && error.status === status && error.code === code && error.message === title,
            `${status} ${code}`,
        );
    }
});

// ------------------------------------------------------------------------------------------------
// The gateway host and the project
// ------------------------------------------------------------------------------------------------

test("the gateway host is an origin, https unless it is a loopback host that was allowed", () => {
    const base = { projectId: PROJECT, accessToken: "token" };
    assert.throws(() => new YogabaseJobsClient({ ...base, gatewayHost: "https://apps.example.test/not-an-origin" }), /origin-only/);
    assert.throws(() => new YogabaseJobsClient({ ...base, gatewayHost: "https://user:pass@apps.example.test" }), /origin-only/);
    assert.throws(() => new YogabaseJobsClient({ ...base, gatewayHost: "https://apps.example.test/?q=1" }), /origin-only/);
    assert.throws(() => new YogabaseJobsClient({ ...base, gatewayHost: "http://apps.example.test" }), /HTTPS/);
    assert.throws(() => new YogabaseJobsClient({ ...base, gatewayHost: "http://apps.example.test", allowInsecureLoopback: true }), /HTTPS/);
    assert.throws(() => new YogabaseJobsClient({ ...base, gatewayHost: "http://localhost:5480" }), /HTTPS/);
    assert.equal(new YogabaseJobsClient({ ...base, gatewayHost: "http://localhost:5480", allowInsecureLoopback: true }).gatewayHost, "http://localhost:5480");
    assert.equal(new YogabaseJobsClient({ ...base, gatewayHost: "http://127.0.0.1:5480", allowInsecureLoopback: true }).gatewayHost, "http://127.0.0.1:5480");
    assert.equal(new YogabaseJobsClient({ ...base, gatewayHost: "https://apps.example.test/" }).gatewayHost, "https://apps.example.test");
    assert.throws(() => new YogabaseJobsClient({ projectId: PROJECT, gatewayHost: "https://apps.example.test", accessToken: "" }), TypeError);
    assert.throws(() => new YogabaseJobsClient({ ...base, gatewayHost: "https://apps.example.test", projectId: "not-a-guid" }), TypeError);
    assert.throws(() => new YogabaseJobsClient({ ...base, gatewayHost: "https://apps.example.test", projectId: "00000000-0000-0000-0000-000000000000" }), TypeError);
});

test("the project in the route is the client's own", async () => {
    const other = "22222222-2222-4222-8222-222222222222";
    const fake = fakeFetch([json(jobDocument())]);
    await client(fake, { projectId: other }).get(JOB);
    assert.equal(fake.calls[0].url, `https://apps.example.test/v1/projects/${other}/jobs/${JOB}`);
});
